-- ==========================================================
-- Place rank & capital helpers

function capitalLevel(capital)
  local capital_al = tonumber(capital) or 0
  if capital == "yes" then
    capital_al = 2
  end
  if capital_al == 0 then
    return nil
  end
  return capital_al
end

function calcRank(place, population, capital_al)
  local rank = 0
  if capital_al and capital_al >= 2 and capital_al <= 4 then
    rank = capital_al
    if population > 3 * 10^6 then
      rank = rank - 2
    elseif population > 1 * 10^6 then
      rank = rank - 1
    elseif population < 100000 then
      rank = rank + 2
    elseif population < 50000 then
      rank = rank + 3
    end
    if place ~= "city" then
      rank = rank + 3
      if place ~= "town" then
        rank = rank + 2
      end
    end
    return rank
  end
  if place ~= "city" and place ~= "town" then
    return nil
  end
  if population > 3 * 10^6 then return 1
  elseif population > 1 * 10^6 then return 2
  elseif population > 500000 then return 3
  elseif population > 200000 then return 4
  elseif population > 100000 then return 5
  elseif population > 75000 then return 6
  elseif population > 50000 then return 7
  elseif population > 25000 then return 8
  elseif population > 10000 then return 9
  end
  return 10
end

-- ==========================================================
-- Park classification (NavApp Nature Reserves & National Parks fix)

local function classifyPark(boundary, leisure, protectClass, protectionTitle)
  local pt = string.lower(protectionTitle or "")
  if protectClass == "98" then return nil end
  if boundary == "national_park" or protectClass == "2" or string.find(pt, "national park", 1, true) then
    return "national_park"
  end
  if leisure == "nature_reserve" or protectClass == "1" or protectClass == "1a" or protectClass == "1b"
     or protectClass == "3" or protectClass == "4" or protectClass == "5" or protectClass == "6"
     or string.find(pt, "nature reserve", 1, true) or string.find(pt, "forest reserve", 1, true)
     or string.find(pt, "biosphere", 1, true) or string.find(pt, "marine park", 1, true) then
    return "nature_reserve"
  end
  if boundary == "protected_area" then
    if protectClass == "22" or string.find(pt, "monument", 1, true) then
      return "nature_reserve"
    end
    if Find("name") ~= "" or Find("name:he") ~= "" then
      return "nature_reserve"
    end
  end
  return nil
end

-- ==========================================================
-- Relations scanning & non-multipolygon relation handling

function relation_scan_function()
  local relType = Find("type")
  local boundary = Find("boundary")
  local route = Find("route")
  if relType == "boundary" and (boundary == "administrative" or boundary == "protected_area") then
    Accept()
  elseif relType == "restriction" or relType:sub(1, 12) == "restriction:" then
    Accept()
  elseif relType == "route" and (route == "hiking" or route == "foot" or route == "bicycle" or route == "mtb" or route == "4wd" or route == "horse") then
    Accept()
  end
end

function relation_function()
  local relType = Find("type")
  local boundary = Find("boundary")
  if relType == "boundary" and boundary == "administrative" then
    write_admin_area_layer()
  elseif relType == "boundary" and boundary == "protected_area" then
    local parkClass = classifyPark(boundary, Find("leisure"), Find("protect_class"), Find("protection_title"))
    if parkClass ~= nil then
      Layer("park", true)
      Attribute("class", parkClass)
      SetNameAttributes()
      parkMinZoom()
    end
  end
end

function write_admin_area_layer()
  local admin_level = tonumber(Find("admin_level"))
  if not admin_level then return end
  if admin_level < 2 or admin_level > admin_area_max_level then return end
  if not HasNames() then return end

  local mz = 0
  if     admin_level >= 3 and admin_level < 5 then mz = 4
  elseif admin_level >= 5 and admin_level < 7 then mz = 8
  elseif admin_level == 7 then mz = 10
  elseif admin_level >= 8 then mz = 12
  end

  Layer("admin_area", true)
  MinZoom(mz)
  AttributeNumeric("admin_level", admin_level)
  SetNameAttributes()

  local name = Find("name")
  if name ~= "" then Attribute("name", name) end
  if Holds("name:en") then Attribute("name_en", Find("name:en")) end
  if Holds("wikidata") then Attribute("wikidata", Find("wikidata")) end
  if Holds("ISO3166-1:alpha2") then Attribute("iso_a2", Find("ISO3166-1:alpha2")) end
  if Holds("ISO3166-2") then Attribute("iso_3166_2", Find("ISO3166-2")) end

  local disputed = Find("disputed")
  if disputed == "yes" then
    AttributeNumeric("disputed", 1)
  else
    AttributeNumeric("disputed", 0)
  end
end

-- ==========================================================
-- Node processing

function node_function()
  -- Write 'aerodrome_label'
  local aeroway = Find("aeroway")
  if aeroway == "aerodrome" then
    Layer("aerodrome_label", false)
    SetNameAttributes()
    Attribute("iata", Find("iata"))
    SetEleAttributes()
    Attribute("icao", Find("icao"))

    local aerodrome_value = Find("aerodrome")
    local class
    if aerodromeValues[aerodrome_value] then class = aerodrome_value else class = "other" end
    Attribute("class", class)
  end

  -- Write 'housenumber'
  local housenumber = Find("addr:housenumber")
  if housenumber ~= "" then
    Layer("housenumber", false)
    Attribute("housenumber", housenumber)
  end

  -- Write 'place'
  local place = Find("place")
  if place ~= "" then
    local mz = 13
    local pop = tonumber(Find("population")) or 0
    local capital = capitalLevel(Find("capital"))
    local rank = calcRank(place, pop, capital)

    if     place == "continent" then mz = 0
    elseif place == "country" then
      mz = ZP.place_country
      if     pop > 50000000 then rank = 1
      elseif pop > 20000000 then rank = 2
      else                       rank = 3 end
    elseif place == "state"             then mz = 4
    elseif place == "province"          then mz = 5
    elseif place == "city"              then mz = ZP.place_city
    elseif place == "town" and pop > 8000 then mz = ZP.place_town_large
    elseif place == "town"              then mz = ZP.place_town
    elseif place == "village" and pop > 2000 then mz = ZP.place_village_large
    elseif place == "village"           then mz = ZP.place_village
    elseif place == "borough"           then mz = 10
    elseif place == "suburb"            then mz = 11
    elseif place == "quarter"           then mz = 12
    elseif place == "hamlet"            then mz = ZP.place_hamlet
    elseif place == "neighbourhood"     then mz = ZP.place_dwelling
    elseif place == "isolated_dwelling" then mz = ZP.place_dwelling
    elseif place == "farm"              then mz = ZP.place_dwelling
    elseif place == "locality"          then mz = 13
    elseif place == "island"            then mz = 12
    end

    Layer("place", false)
    Attribute("class", place)
    MinZoom(mz)
    if rank then AttributeNumeric("rank", rank) end
    if capital then AttributeNumeric("capital", capital) end
    if place == "country" then
      local iso_a2 = Find("ISO3166-1:alpha2")
      while iso_a2 == "" do
        local rel, role = NextRelation()
        if not rel then break end
        if role == "label" then
          iso_a2 = FindInRelation("ISO3166-1:alpha2")
        end
      end
      Attribute("iso_a2", iso_a2)
    end
    SetNameAttributes()
    return
  end

  -- Write 'fuel_line' power towers
  if Find("power") == "tower" then
    Layer("fuel_line", false)
    Attribute("class", "tower")
    MinZoom(fuelMinzoom)
  end

  -- Write 'poi'
  local rank, class, subclass = GetPOIRank()
  if rank then WritePOI(class, subclass, rank) end

  -- Write 'mountain_peak' and 'water_name'
  local natural = Find("natural")
  if natural == "peak" or natural == "volcano" or natural == "saddle" then
    Layer("mountain_peak", false)
    SetEleAttributes()
    AttributeNumeric("rank", 1)
    Attribute("class", natural)
    SetNameAttributes()
    return
  end
  if natural == "bay" then
    Layer("water_name", false)
    MinZoom(14)
    SetNameAttributes()
    return
  end
end

-- ==========================================================
-- Routing, flood, fuel, and transportation helpers

function parseMaxspeed(v)
  if v == "" then return nil end
  if v == "walk" then return 5 end
  local num = tonumber(v:match("^%s*(%d+%.?%d*)"))
  if not num or num <= 0 then return nil end
  if v:find("mph") or v:find("MPH") then return num * 1.609344 end
  if v:find("knots") then return num * 1.852 end
  return num
end

function parseLeadingNumber(v)
  if v == "" then return nil end
  return tonumber(v:match("^%s*(-?%d+%.?%d*)"))
end

function parseDuration(v)
  if v == "" then return nil end
  local h, m, s = v:match("^(%d+):(%d+):(%d+)$")
  if h then return tonumber(h) * 3600 + tonumber(m) * 60 + tonumber(s) end
  local h2, m2 = v:match("^(%d+):(%d+)$")
  if h2 then return tonumber(h2) * 3600 + tonumber(m2) * 60 end
  local n = tonumber(v)
  if n and n > 0 then return n * 60 end
  return nil
end

function write_routing_attributes(is_road, is_ferry)
  local mz = routingMinzoom

  if is_ferry then
    local duration = parseDuration(Find("duration"))
    if duration then AttributeNumeric("duration", duration, mz) end
    if Holds("motor_vehicle") then Attribute("motor_vehicle", Find("motor_vehicle"), mz) end
    if Holds("motorcar")      then Attribute("motorcar",      Find("motorcar"),      mz) end
    if Holds("foot")          then Attribute("foot",          Find("foot"),          mz) end
    if Holds("bicycle")       then Attribute("bicycle",       Find("bicycle"),       mz) end
    if Holds("access")        then Attribute("access",        Find("access"),        mz) end
    return
  end

  if not is_road then return end

  local maxspeed = parseMaxspeed(Find("maxspeed"))
  if maxspeed then AttributeNumeric("maxspeed", maxspeed, mz) end

  local lanes = parseLeadingNumber(Find("lanes"))
  if lanes and lanes > 0 then AttributeNumeric("lanes", lanes, 12) end

  local surface = Find("surface")
  if surface ~= "" then Attribute("surface_detail", surface, mz) end

  -- Track / hiking difficulty attributes needed at z12+ for NavApp track styling & routing
  if Holds("tracktype")        then Attribute("tracktype",        Find("tracktype"),        12) end
  if Holds("smoothness")       then Attribute("smoothness",       Find("smoothness"),       12) end
  if Holds("sac_scale")        then Attribute("sac_scale",        Find("sac_scale"),        12) end
  if Holds("trail_visibility") then Attribute("trail_visibility", Find("trail_visibility"), mz) end

  local incline = parseLeadingNumber(Find("incline"))
  if incline then AttributeNumeric("incline", incline, mz) end

  local width = parseLeadingNumber(Find("width"))
  if width and width > 0 then AttributeNumeric("width", width, mz) end

  if Holds("motor_vehicle") then Attribute("motor_vehicle", Find("motor_vehicle"), mz) end
  if Holds("motorcar")      then Attribute("motorcar",      Find("motorcar"),      mz) end
  if Holds("hgv")           then Attribute("hgv",           Find("hgv"),           mz) end

  local maxheight = parseLeadingNumber(Find("maxheight"))
  if maxheight then AttributeNumeric("maxheight", maxheight, mz) end
  local maxweight = parseLeadingNumber(Find("maxweight"))
  if maxweight then AttributeNumeric("maxweight", maxweight, mz) end

  if Holds("barrier") then Attribute("barrier", Find("barrier"), mz) end

  write_turn_restrictions(mz)
end

function write_turn_restrictions(mz)
  RestartRelations()

  local tokens = nil
  while true do
    local rel_id, role = NextRelation()
    if not rel_id then break end
    local t = FindInRelation("type")
    if t == "restriction" or t:sub(1, 12) == "restriction:" then
      local value = FindInRelation("restriction")
      if value == "" and t ~= "restriction" then value = FindInRelation(t) end
      if value ~= "" then
        local token = rel_id .. ":" .. (role or "") .. ":" .. value .. ":" .. FindInRelation("except")
        tokens = tokens and (tokens .. "|" .. token) or token
      end
    end
  end
  if tokens then Attribute("restrictions", tokens, mz) end
end

function write_to_transportation_layer(minzoom, highway_class, subclass, ramp, service, is_rail, is_road, is_area, trail)
  local effectiveMinzoom = minzoom
  if trail and not is_area then
    if trail.colour ~= "" or trail.osmc_symbol ~= "" then
      effectiveMinzoom = math.min(effectiveMinzoom, 4)
    end
  end

  Layer("transportation", is_area)
  SetZOrder()
  Attribute("class", highway_class)
  if subclass and subclass ~= "" then
    Attribute("subclass", subclass)
  end
  local layer = tonumber(Find("layer")) or 0
  AttributeNumeric("layer", math.floor(layer))
  SetBrunnelAttributes()

  if is_area then
    SetMinZoomByAreaWithLimit(effectiveMinzoom)
    return
  end

  MinZoom(effectiveMinzoom)
  if ramp then AttributeNumeric("ramp", 1) end

  if (is_rail or highway_class == "service") and (service and service ~= "") then
    Attribute("service", service)
  end

  local embankment = Find("embankment")
  if (embankment ~= "" and embankment ~= "no") or Find("man_made") == "embankment" then
    AttributeBoolean("embankment", true, floodMinzoom)
  end
  local cutting = Find("cutting")
  if cutting ~= "" and cutting ~= "no" then
    AttributeBoolean("cutting", true, floodMinzoom)
  end

  local accessMinzoom = 9
  if is_road then
    local oneway = Find("oneway")
    if oneway == "yes" or oneway == "1" then
      AttributeNumeric("oneway", 1)
    elseif oneway == "-1" then
      AttributeNumeric("oneway", -1)
    end

    local surface = Find("surface")
    local surfaceMinzoom = 12
    if pavedValues[surface] then
      Attribute("surface", "paved", surfaceMinzoom)
    elseif unpavedValues[surface] then
      Attribute("surface", "unpaved", surfaceMinzoom)
    elseif surface ~= "" then
      Attribute("surface", surface, surfaceMinzoom)
    end

    if Holds("access")  then Attribute("access",  Find("access"),  accessMinzoom) end
    if Holds("bicycle") then Attribute("bicycle", Find("bicycle"), accessMinzoom) end
    if Holds("foot")    then Attribute("foot",    Find("foot"),    accessMinzoom) end
    if Holds("horse")   then Attribute("horse",   Find("horse"),   accessMinzoom) end
    AttributeBoolean("toll", Find("toll") == "yes", accessMinzoom)
    if Find("expressway") == "yes" then AttributeBoolean("expressway", true, 7) end
    if Holds("mtb:scale") then Attribute("mtb_scale", Find("mtb:scale"), 10) end
  end

  if trail then
    if trail.colour ~= "" then Attribute("colour", trail.colour) end
    if trail.colour2 ~= "" then Attribute("colour2", trail.colour2) end
    if trail.osmc_symbol ~= "" then Attribute("osmc_symbol", trail.osmc_symbol) end
    if trail.ref ~= "" then Attribute("ref", trail.ref) end
    if trail.network ~= "" then Attribute("network", trail.network) end
    if trail.is_int then AttributeNumeric("is_int", 1) end
    if trail.description then Attribute("navapp_description", trail.description) end
    if trail.hazard then Attribute("navapp_hazard", trail.hazard) end
    if trail.activities then Attribute("navapp_activities", trail.activities) end
  end

  write_routing_attributes(is_road, highway_class == "ferry")
end

function write_flood_defence(class, is_area)
  Layer("flood_defence", is_area)
  Attribute("class", class)

  local ele = parseLeadingNumber(Find("ele"))
  if ele then AttributeNumeric("crest_m", ele) end

  local height = parseLeadingNumber(Find("height"))
  if height and height > 0 then AttributeNumeric("height_m", height) end

  local width = parseLeadingNumber(Find("width"))
  if width and width > 0 then AttributeNumeric("width_m", width) end

  if Holds("material") then Attribute("material", Find("material")) end
  if HasNames() then SetNameAttributes() end

  if is_area then SetMinZoomByAreaWithLimit(floodMinzoom) else MinZoom(floodMinzoom) end
end

function write_fuel_line(class)
  Layer("fuel_line", false)
  Attribute("class", class)

  local width = parseLeadingNumber(Find("width"))
  if width and width > 0 then AttributeNumeric("width_m", width) end

  if class == "tree_row" then
    local leaf = Find("leaf_type")
    if leafTypeValues[leaf] then Attribute("leaf_type", leaf) end
  end

  MinZoom(fuelMinzoom)
end

function write_fuel_attributes(class)
  if class == "wood" then
    local leaf = Find("leaf_type")
    if leafTypeValues[leaf] then Attribute("leaf_type", leaf, fuelMinzoom) end
    local cycle = Find("leaf_cycle")
    if leafCycleValues[cycle] then Attribute("leaf_cycle", cycle, fuelMinzoom) end
  elseif class == "farmland" then
    local crop = Find("crop")
    if crop ~= "" then Attribute("crop", crop, fuelMinzoom) end
  end
end

-- ==========================================================
-- Way processing

function way_function()
  local route            = Find("route")
  local highway          = Find("highway")
  local waterway         = Find("waterway")
  local water            = Find("water")
  local building         = Find("building")
  local natural          = Find("natural")
  local historic         = Find("historic")
  local landuse          = Find("landuse")
  local leisure          = Find("leisure")
  local amenity          = Find("amenity")
  local aeroway          = Find("aeroway")
  local railway          = Find("railway")
  local service          = Find("service")
  local sport            = Find("sport")
  local shop             = Find("shop")
  local tourism          = Find("tourism")
  local man_made         = Find("man_made")
  local boundary         = Find("boundary")
  local aerialway        = Find("aerialway")
  local public_transport = Find("public_transport")
  local place            = Find("place")
  local power            = Find("power")
  local is_closed        = IsClosed()
  local housenumber      = Find("addr:housenumber")
  local write_name       = false
  local construction     = Find("construction")

  -- Miscellaneous preprocessing
  if Find("disused") == "yes" then return end
  if boundary ~= "" and Find("protection_title") == "National Forest" and Find("operator") == "United States Forest Service" then return end
  if highway == "proposed" then return end
  if aerowayBuildings[aeroway] then building = "yes"; aeroway = "" end
  if landuse == "field" then landuse = "farmland" end
  if landuse == "meadow" and Find("meadow") == "agricultural" then landuse = "farmland" end

  if place == "island" then
    LayerAsCentroid("place")
    Attribute("class", place)
    MinZoom(10)
    local pop = tonumber(Find("population")) or 0
    local rank = calcRank(place, pop, nil)
    if rank then AttributeNumeric("rank", rank) end
    SetNameAttributes()
  end

  -- Guarded NextRelation() loop for admin boundaries + hiking/4x4 route relations
  local admin_level = 11
  local isBoundary = (boundary == "administrative")
  local boundaryNameEn = Find("name:en")
  if isBoundary then
    admin_level = math.min(admin_level, tonumber(Find("admin_level")) or 11)
  end

  local routeColour  = Find("colour")
  local routeColour2 = ""
  local routeOsmc    = Find("osmc:symbol")
  local routeRef     = Find("ref")
  local routeNetwork = Find("network")

  while true do
    local rel = NextRelation()
    if not rel then break end
    local relType = FindInRelation("type")
    if relType == "boundary" and FindInRelation("boundary") == "administrative" then
      isBoundary = true
      admin_level = math.min(admin_level, tonumber(FindInRelation("admin_level")) or 11)
      if boundaryNameEn == "" then
        boundaryNameEn = FindInRelation("name:en")
      end
    elseif relType == "route" then
      local c = FindInRelation("colour")
      if routeColour == "" then
        routeColour = c
      elseif c ~= "" and c ~= routeColour and routeColour2 == "" then
        routeColour2 = c
      end
      if routeOsmc == "" then routeOsmc = FindInRelation("osmc:symbol") end
      if routeRef == "" then routeRef = FindInRelation("ref") end
      if routeNetwork == "" then routeNetwork = FindInRelation("network") end
    end
  end

  -- Administrative boundaries (lines + Area A/B/H1 polygons)
  if isBoundary and Find("maritime") ~= "yes" then
    local mz = 0
    if     admin_level >= 3 and admin_level < 5 then mz = 4
    elseif admin_level >= 5 and admin_level < 7 then mz = 8
    elseif admin_level == 7 then mz = 10
    elseif admin_level >= 8 then mz = 12
    end

    local isAreaAB = is_closed and (boundaryNameEn == "Area A" or boundaryNameEn == "Area B" or boundaryNameEn == "Area H1")
    Layer("boundary", isAreaAB)
    AttributeNumeric("admin_level", admin_level)
    MinZoom(mz)
    if boundaryNameEn ~= "" then Attribute("name:en", boundaryNameEn) end
    if Find("disputed") == "yes" then
      AttributeNumeric("disputed", 1)
    else
      AttributeNumeric("disputed", 0)
    end
  end

  -- Administrative areas as NAMED POLYGONS ('admin_area')
  if Find("type") == "boundary" and boundary == "administrative" then
    write_admin_area_layer()
  end

  -- Resolve NavApp enrichment lookup by way ID or SPNI ref
  local wayIdStr = tostring(Id())
  local e = enrichment.ways[wayIdStr]
  if not e and routeRef ~= "" then
    e = enrichment.refs[routeRef]
  end
  local trailMeta = {
    colour = routeColour,
    colour2 = routeColour2,
    osmc_symbol = routeOsmc,
    ref = routeRef,
    network = routeNetwork,
    is_int = false,
    description = nil,
    hazard = nil,
    activities = nil,
  }
  if e then
    if trailMeta.colour == "" and e.colour then trailMeta.colour = e.colour end
    if trailMeta.osmc_symbol == "" and e.osmc_symbol then trailMeta.osmc_symbol = e.osmc_symbol end
    if trailMeta.ref == "" and e.ref then trailMeta.ref = e.ref end
    if e.description then trailMeta.description = e.description end
    if e.hazard then trailMeta.hazard = e.hazard end
    if e.activities then trailMeta.activities = e.activities end
  end
  if string.find(trailMeta.osmc_symbol, "orange:orange:white_right:blue_stripe", 1, true)
     or trailMeta.network == "iwn"
     or trailMeta.ref == "INT" then
    trailMeta.is_int = true
  end

  -- Aerialways ('transportation' and 'transportation_name')
  if aerialway ~= "" then
    write_to_transportation_layer(12, "aerialway", aerialway, false, nil, false, false, is_closed, nil)
    if HasNames() then
      Layer("transportation_name", false)
      MinZoom(12)
      SetNameAttributes()
      Attribute("class", "aerialway")
      Attribute("subclass", aerialway)
    end
  end

  -- Roads ('transportation' and 'transportation_name')
  if highway ~= "" or public_transport == "platform" then
    local is_area = (public_transport == "platform" or Find("area") == "yes") and is_closed

    local h = highway
    local is_road = true
    if h == "" then
      h = public_transport
      is_road = false
    end
    local subclass = nil
    local under_construction = false
    if highway == "construction" and construction ~= "" then
      h = construction
      under_construction = true
    end
    local minzoom = INVALID_ZOOM
    if majorRoadValues[h]        then minzoom = ZP.road_motorway
    elseif h == "trunk"          then minzoom = ZP.road_trunk
    elseif h == "primary"        then minzoom = ZP.road_primary
    elseif z9RoadValues[h]       then minzoom = 9
    elseif z10RoadValues[h]      then minzoom = 10
    elseif z11RoadValues[h]      then minzoom = 11
    elseif z12MinorRoadValues[h] then
      minzoom = 12
      subclass = h
      h = "minor"
    elseif z12OtherRoadValues[h]     then minzoom = 12
    elseif trackServiceRoadValues[h] then minzoom = ZP.road_track_service
    elseif pathValues[h] then
      minzoom = ZP.path_from[h] or ZP.path_default
      subclass = h
      h = "path"
    end

    -- Links (ramp)
    local ramp = false
    if linkValues[h] then
      local splitHighway = split(h, "_")
      h = splitHighway[1]
      ramp = true
    end

    -- Construction
    if under_construction then
      h = h .. "_construction"
    end

    -- Drop underground platforms
    local layerNumeric = tonumber(Find("layer"))
    if not is_road and layerNumeric ~= nil and layerNumeric < 0 then
      minzoom = INVALID_ZOOM
    end

    -- Drop all areas except infrastructure for pedestrians handled above
    if is_area and h ~= "path" then
      minzoom = INVALID_ZOOM
    end

    if minzoom <= 14 then
      write_to_transportation_layer(minzoom, h, subclass, ramp, service, false, is_road, is_area, trailMeta)

      -- Write names
      if not is_closed and (HasNames() or Holds("ref") or trailMeta.ref ~= "") then
        local nameMz
        if     h == "motorway"  then nameMz = ZP.name_motorway
        elseif h == "trunk"     then nameMz = ZP.name_trunk
        elseif h == "primary"   then nameMz = ZP.name_primary
        elseif h == "secondary" then nameMz = ZP.name_secondary
        elseif h == "tertiary"  then nameMz = ZP.name_tertiary
        elseif h == "minor"     then nameMz = ZP.name_minor
        elseif h == "track"     then nameMz = ZP.name_track
        elseif h == "service"   then nameMz = ZP.name_service
        elseif h == "path"      then nameMz = ZP.name_path
        else                         nameMz = ZP.name_other
        end
        Layer("transportation_name", false)
        MinZoom(nameMz)
        SetNameAttributes()
        Attribute("class", h)
        if trailMeta.network ~= "" then
          Attribute("network", trailMeta.network)
        else
          Attribute("network", "road")
        end
        if subclass then Attribute("subclass", subclass) end
        if trailMeta.colour ~= "" then Attribute("colour", trailMeta.colour) end
        if trailMeta.osmc_symbol ~= "" then Attribute("osmc_symbol", trailMeta.osmc_symbol) end
        local ref = Find("ref")
        if ref == "" then ref = trailMeta.ref end
        if ref ~= "" then
          Attribute("ref", ref)
          AttributeNumeric("ref_length", ref:len())
        end
      end
    end
  end

  -- Railways ('transportation' and 'transportation_name')
  if railway ~= "" then
    local class = railwayClasses[railway]
    if class then
      local minzoom = 14
      local usage = Find("usage")
      if railway == "rail" and service == "" then
        if usage == "main" then minzoom = 8 else minzoom = 10 end
      elseif railway == "narrow_gauge" and service == "" then
        minzoom = 10
      elseif railway == "light_rail" and service == "" then
        minzoom = 11
      end
      write_to_transportation_layer(minzoom, class, railway, false, service, true, false, is_closed, nil)

      if HasNames() then
        Layer("transportation_name", false)
        SetNameAttributes()
        MinZoom(14)
        Attribute("class", class)
      end
    end
  end

  -- Pier / Bridge
  if manMadeRoadValues[man_made] then
    write_to_transportation_layer(13, man_made, nil, false, nil, false, false, is_closed, nil)
  end

  -- Ferry
  if route == "ferry" then
    write_to_transportation_layer(9, "ferry", nil, false, nil, false, false, is_closed, nil)
    if HasNames() then
      Layer("transportation_name", false)
      SetNameAttributes()
      MinZoom(12)
      Attribute("class", "ferry")
    end
  end

  -- Aeroway & aerodrome_label
  if aeroway ~= "" then
    Layer("aeroway", is_closed)
    MinZoom(ZP.aeroway[aeroway] or ZP.aeroway_default)
    Attribute("class", aeroway)
    Attribute("ref", Find("ref"))
    write_name = true
  end

  if aeroway == "aerodrome" then
    LayerAsCentroid("aerodrome_label")
    SetNameAttributes()
    Attribute("iata", Find("iata"))
    SetEleAttributes()
    Attribute("icao", Find("icao"))

    local aerodrome = Find(aeroway)
    local class
    if aerodromeValues[aerodrome] then class = aerodrome else class = "other" end
    Attribute("class", class)
  end

  -- Waterway & water_name
  local intermittent = string.lower(Find("intermittent"))
  local isIntermittent = (intermittent == "yes" or intermittent == "1" or intermittent == "true")

  if waterwayClasses[waterway] and not is_closed then
    Layer("waterway", false)
    if isIntermittent then AttributeNumeric("intermittent", 1) else AttributeNumeric("intermittent", 0) end
    Attribute("class", waterway)
    SetNameAttributes()
    SetBrunnelAttributes()
    MinZoom(waterway == "river" and Holds("name") and 8 or 12)
    local channel_width = parseLeadingNumber(Find("width"))
    if channel_width and channel_width > 0 then
      AttributeNumeric("width_m", channel_width, floodMinzoom)
    end
    local channel_depth = parseLeadingNumber(Find("depth"))
    if channel_depth and channel_depth > 0 then
      AttributeNumeric("depth_m", channel_depth, floodMinzoom)
    end
  elseif waterway == "boatyard" then
    Layer("landuse", is_closed); Attribute("class", "industrial"); MinZoom(12)
  elseif waterway == "dam" then
    Layer("building", is_closed)
    if is_closed then SetBuildingHeightAttributes() end
  elseif waterway == "fuel" then
    Layer("landuse", is_closed); Attribute("class", "industrial"); MinZoom(14)
  end

  if waterwayClasses[waterway] and not is_closed and HasNames() then
    Layer("water_name", false)
    MinZoom(14)
    Attribute("class", waterway)
    SetNameAttributes()
  end

  -- Flood defence ('flood_defence')
  local flood_class = floodDefenceManMade[man_made]
                   or floodDefenceBarrier[Find("barrier")]
                   or floodDefenceWaterway[waterway]
                   or floodDefenceNatural[natural]
                   or floodDefenceHistoric[historic]
  if flood_class then
    write_flood_defence(flood_class, is_closed)
  end

  -- Linear fuel features ('fuel_line')
  local fuel_line_class = fuelLineBarrier[Find("barrier")]
                       or fuelLineNatural[natural]
                       or fuelLineManMade[man_made]
                       or fuelLinePower[power]
  if fuel_line_class then
    if fuel_line_class == "cutline" and Find("cutline") == "firebreak" then
      fuel_line_class = "firebreak"
    end
    write_fuel_line(fuel_line_class)
  end

  -- Buildings ('building')
  if building ~= "" and is_closed then
    Layer("building", true)
    SetBuildingHeightAttributes()
    if HasNames() then SetNameAttributes() end
    SetMinZoomByArea()
  end

  -- Housenumber
  if housenumber ~= "" then
    LayerAsCentroid("housenumber")
    Attribute("housenumber", housenumber)
  end

  -- Water polygons ('water' & 'water_name')
  if natural == "water" or leisure == "swimming_pool" or landuse == "reservoir" or landuse == "basin" or waterClasses[waterway] then
    if Find("covered") == "yes" or not is_closed then return end
    local class = "lake"
    if waterway ~= "" then class = "river" end
    if class == "lake" and Find("wikidata") == "Q192770" then return end

    Layer("water", true)
    if class == "lake" then MinZoom(areaZoom(ZP.lake_from)) else SetMinZoomByArea() end
    Attribute("class", class)
    if isIntermittent then AttributeNumeric("intermittent", 1) end

    if HasNames() and natural == "water" and water ~= "basin" and water ~= "wastewater" then
      LayerAsCentroid("water_name")
      SetNameAttributes()
      MinZoom(areaZoom(ZP.water_name_from))
      Attribute("class", class)
    end
    if (water == "pond" or water == "stream_pool") and HasNames() then
      LayerAsCentroid("poi")
      SetNameAttributes()
      Attribute("class", "water")
      Attribute("subclass", water)
      MinZoom(12)
    end
    return
  end

  -- Landcover & Landuse
  local l = landuse
  if l == "" then l = natural end
  if l == "" then l = leisure end
  if landcoverKeys[l] then
    Layer("landcover", true)
    if landcoverKeys[l] == "wetland" then
      MinZoom(areaZoom(ZP.wetland_from))
    else
      MinZoom(areaZoom(ZP.landcover_from))
    end
    Attribute("class", landcoverKeys[l])
    if l == "wetland" then
      Attribute("subclass", Find("wetland"))
    else
      Attribute("subclass", l)
    end
    write_fuel_attributes(landcoverKeys[l])
    write_name = true
  else
    if l == "" then l = amenity end
    if l == "" then l = tourism end
    if landuseKeys[l] and is_closed then
      Layer("landuse", true)
      Attribute("class", l)
      if l == "residential" then
        if Area() < ZRES8^2 then MinZoom(8) else SetMinZoomByArea() end
      else
        local from = ZP.landuse_from[l]
        if from then
          MinZoom(math.min(areaZoom(from), ZP.landuse_default))
        else
          MinZoom(ZP.landuse_default)
        end
      end
      write_name = true
    end
  end

  if (power == "substation" or power == "sub_station" or power == "plant") and is_closed then
    Layer("landuse", true)
    Attribute("class", power)
    MinZoom(13)
  end
  if man_made == "breakwater" and is_closed then
    Layer("landuse", true)
    Attribute("class", "breakwater")
    MinZoom(11)
  end

  -- Parks & Protected Areas ('park')
  if (boundary == "protected_area" or boundary == "national_park" or leisure == "nature_reserve") and is_closed then
    local parkClass = classifyPark(boundary, leisure, Find("protect_class"), Find("protection_title"))
    if parkClass ~= nil then
      Layer("park", true)
      Attribute("class", parkClass)
      SetNameAttributes()
      parkMinZoom()
    end
  end

  -- POIs ('poi')
  local rank, class, subclass = GetPOIRank()
  if rank then WritePOI(class, subclass, rank); return end

  -- Catch-all named buildings / landcover / landuse centroids
  if (building ~= "" or write_name) and HasNames() then
    LayerAsCentroid("poi")
    SetNameAttributes()
    if write_name then rank = 6 else rank = 25 end
    AttributeNumeric("rank", rank)
    MinZoom(14)
  end
end

-- Remap coastlines & natural earth shapefiles
function attribute_function(attr, layer)
  if attr["featurecla"] == "Glaciated areas" then
    return { subclass = "glacier" }
  elseif attr["featurecla"] == "Antarctic Ice Shelf" then
    return { subclass = "ice_shelf" }
  elseif attr["featurecla"] == "Urban area" then
    return { class = "residential" }
  elseif layer == "ocean" then
    return { class = "ocean" }
  else
    return attr
  end
end

-- ==========================================================
-- Common functions

function WritePOI(class, subclass, rank)
  LayerAsCentroid("poi")
  if ZP.poi_early[class] or navappEarlyPoiSubclasses[subclass] or class == "place_of_worship" or class == "monastery" or class == "cemetery" then
    MinZoom(12)
  elseif rank <= 4 then
    MinZoom(ZP.poi)
  else
    MinZoom(14)
  end

  SetNameAttributes()
  AttributeNumeric("rank", rank)
  Attribute("class", class)
  Attribute("subclass", subclass)

  if subclass == "storage_tank" and Holds("content") then
    Attribute("content", Find("content"))
  end
  if subclass == "tomb" and Holds("tomb") then
    Attribute("tomb", Find("tomb"))
  end

  local layer = tonumber(Find("layer")) or 0
  AttributeNumeric("layer", math.floor(layer))
  AttributeBoolean("indoor", (Find("indoor") == "yes"))
  local level = tonumber(Find("level"))
  if level then
    AttributeNumeric("level", math.floor(level))
  end
end

function HasNames()
  if Holds("name") then return true end
  if preferred_language and Holds("name:" .. preferred_language) then return true end
  for _, lang in ipairs(additional_languages) do
    if Holds("name:" .. lang) then return true end
  end
  return false
end

function SetNameAttributes()
  local name = Find("name")
  local nameHe = Find("name:he")
  local nameEn = Find("name:en")
  local primary = name
  if primary == "" then
    primary = nameEn ~= "" and nameEn or nameHe
  end

  if primary ~= "" then
    Attribute("name", primary)
  end

  local iname
  local main_written = primary
  if preferred_language and Holds("name:" .. preferred_language) then
    iname = Find("name:" .. preferred_language)
    Attribute(preferred_language_attribute, iname)
    if iname ~= primary and default_language_attribute and primary ~= "" then
      Attribute(default_language_attribute, primary)
    else
      main_written = iname
    end
  elseif primary ~= "" then
    Attribute(preferred_language_attribute, primary)
  end

  for _, lang in ipairs(additional_languages) do
    iname = Find("name:" .. lang)
    if iname ~= "" then
      Attribute("name:" .. lang, iname)
    end
  end
end

function SetEleAttributes()
  local ele = Find("ele")
  if ele ~= "" then
    local meter = math.floor(parseLeadingNumber(ele) or 0)
    local feet = math.floor(meter * 3.2808399)
    AttributeNumeric("ele", meter)
    AttributeNumeric("ele_ft", feet)
  end
end

function SetBrunnelAttributes()
  if Find("bridge") == "yes" or Find("man_made") == "bridge" then Attribute("brunnel", "bridge")
  elseif Find("tunnel") == "yes" then Attribute("brunnel", "tunnel")
  elseif Find("ford") == "yes" then Attribute("brunnel", "ford")
  end
end

function areaZoom(from)
  local area = Area()
  local z
  if     area > ZRES3^2  then z = 4
  elseif area > ZRES4^2  then z = 5
  elseif area > ZRES5^2  then z = 6
  elseif area > ZRES6^2  then z = 7
  elseif area > ZRES7^2  then z = 8
  elseif area > ZRES8^2  then z = 9
  elseif area > ZRES9^2  then z = 10
  elseif area > ZRES10^2 then z = 11
  elseif area > ZRES11^2 then z = 12
  elseif area > ZRES12^2 then z = 13
  else                        z = 14 end
  if z < from then z = from end
  return z
end

function parkMinZoom()
  MinZoom(math.min(areaZoom(ZP.park_from), ZP.park_cap))
end

function SetMinZoomByArea()
  SetMinZoomByAreaWithLimit(0)
end

function SetMinZoomByAreaWithLimit(minzoom)
  local area = Area()
  if     minzoom <= 6  and area > ZRES5^2  then MinZoom(6)
  elseif minzoom <= 7  and area > ZRES6^2  then MinZoom(7)
  elseif minzoom <= 8  and area > ZRES7^2  then MinZoom(8)
  elseif minzoom <= 9  and area > ZRES8^2  then MinZoom(9)
  elseif minzoom <= 10 and area > ZRES9^2  then MinZoom(10)
  elseif minzoom <= 11 and area > ZRES10^2 then MinZoom(11)
  elseif minzoom <= 12 and area > ZRES11^2 then MinZoom(12)
  elseif minzoom <= 13 and area > ZRES12^2 then MinZoom(13)
  else                                          MinZoom(14) end
end

function GetPOIRank()
  for k, list in pairs(poiTags) do
    local v = Find(k)
    if v ~= "" and list[v] then
      local class = poiClasses[v] or k
      local rank = poiClassRanks[class] or 25
      local subclassKey = poiSubClasses[v]
      if subclassKey then
        class = v
        local subVal = Find(subclassKey)
        if subVal ~= "" then
          v = subVal
        end
      end
      return rank, class, v
    end
  end

  local shop = Find("shop")
  if shop ~= "" then return poiClassRanks["shop"], "shop", shop end

  return nil, nil, nil
end

