local buildingColourAliases = {
  cream = "#FFFDD0",
  offwhite = "#FAF9F6",
  sand = "#E5D3B3",
  sandstone = "#D2B48C",
  terracotta = "#E2725B",
  ochre = "#CC7722",
  burgundy = "#800020",
  lightbrown = "#B5651D",
  darkbrown = "#5C4033",
}

local function normalizeBuildingColour(raw)
  if raw == "" then return nil end
  local first = string.match(raw, "^([^;]+)")
  if not first then return nil end
  local cleaned = string.lower(first:match("^%s*(.-)%s*$"))
  if cleaned == "" or cleaned == "yes" or cleaned == "no" or cleaned == "none" then
    return nil
  end
  if string.match(cleaned, "^#%x%x%x$") or string.match(cleaned, "^#%x%x%x%x%x%x$") then
    return cleaned
  end
  if string.match(cleaned, "^%x%x%x%x%x%x$") then
    return "#" .. cleaned
  end
  local compact = cleaned:gsub("[%s_%-]", "")
  if validBuildingCssColors[compact] then
    return compact
  end
  if buildingColourAliases[compact] then
    return buildingColourAliases[compact]
  end
  return nil
end

function SetBuildingColourAttribute()
  local raw = Find("building:colour")
  if raw == "" then raw = Find("roof:colour") end
  if raw == "" then raw = Find("building:color") end
  if raw == "" then raw = Find("colour") end
  local colour = normalizeBuildingColour(raw)
  if colour then
    Attribute("colour", colour)
  end
end

function SetBuildingHeightAttributes()
  local height = parseLeadingNumber(Find("height"))
  local minHeight = parseLeadingNumber(Find("min_height"))
  local levels = parseLeadingNumber(Find("building:levels"))
  local minLevel = parseLeadingNumber(Find("building:min_level"))

  local renderHeight = BUILDING_FLOOR_HEIGHT
  if (height and height > 0) or (levels and levels > 0) then
    renderHeight = (height and height > 0) and height or (levels * BUILDING_FLOOR_HEIGHT)
  end
  local renderMinHeight = 0
  if (minHeight and minHeight > 0) or (minLevel and minLevel > 0) then
    renderMinHeight = (minHeight and minHeight > 0) and minHeight or (minLevel * BUILDING_FLOOR_HEIGHT)
  end

  -- Fix upside-down buildings
  if renderHeight < renderMinHeight then
    renderHeight = renderHeight + renderMinHeight
  end

  AttributeNumeric("render_height", renderHeight)
  AttributeNumeric("render_min_height", renderMinHeight)
  SetBuildingColourAttribute()
end

function SetZOrder()
  local highway = Find("highway")
  local layer = tonumber(Find("layer"))
  local bridge = Find("bridge")
  local tunnel = Find("tunnel")
  local zOrder = 0
  if bridge ~= "" and bridge ~= "no" then
    zOrder = zOrder + 10
  elseif tunnel ~= "" and tunnel ~= "no" then
    zOrder = zOrder - 10
  end
  if layer ~= nil then
    if layer > 7 then layer = 7
    elseif layer < -7 then layer = -7 end
    zOrder = zOrder + layer * 10
  end
  local hwClass = 3
  if highway == "motorway" then hwClass = 9
  elseif highway == "trunk" then hwClass = 8
  elseif highway == "primary" then hwClass = 6
  elseif highway == "secondary" then hwClass = 5
  elseif highway == "tertiary" then hwClass = 4
  end
  zOrder = zOrder + hwClass
  ZOrder(zOrder)
end

function split(inputstr, sep)
  if sep == nil then sep = "%s" end
  local t = {}
  local i = 1
  for str in string.gmatch(inputstr, "([^" .. sep .. "]+)") do
    t[i] = str
    i = i + 1
  end
  return t
end
